const tz = 'Europe/Rome';
const now = DateTime.now().setZone(tz);
const rows = $input.all().filter(i => i.json && i.json.recorded_at);
let start = rows.length
  ? DateTime.fromISO(rows[0].json.recorded_at).setZone(tz).startOf('day')
  : now.minus({ days: 7 }).startOf('day');
// Google Health caps heart-rate, total-calories and active-minutes roll-ups at 14 days per request
const earliest = now.minus({ days: 13 }).startOf('day');
if (start < earliest) start = earliest;
const end = now.plus({ days: 1 }).startOf('day');
const civil = d => ({ date: { year: d.year, month: d.month, day: d.day }, time: { hours: 0, minutes: 0, seconds: 0, nanos: 0 } });
const BASE = 'https://health.googleapis.com/v4/users/me/dataTypes/';
const rollup = (metric, dataType) => ({
  metric,
  kind: 'rollup',
  method: 'POST',
  url: BASE + dataType + '/dataPoints:dailyRollUp',
  body: { range: { start: civil(start), end: civil(end) }, windowSizeDays: 1, pageSize: 14 },
});
const list = (metric, dataType, filter, pageSize) => ({
  metric,
  kind: 'list',
  method: 'GET',
  url: BASE + dataType + '/dataPoints?pageSize=' + pageSize + '&filter=' + encodeURIComponent(filter),
  body: {},
});
const startDate = start.toISODate();
const startUtc = start.toUTC().toISO({ suppressMilliseconds: true });
const requests = [
  rollup('steps', 'steps'),
  rollup('distance', 'distance'),
  rollup('calories', 'total-calories'),
  rollup('active_minutes', 'active-minutes'),
  rollup('active_zone_minutes', 'active-zone-minutes'),
  rollup('heart_rate', 'heart-rate'),
  rollup('weight', 'weight'),
  list('resting_heart_rate', 'daily-resting-heart-rate', 'daily_resting_heart_rate.date >= "' + startDate + '"', 100),
  list('hrv', 'daily-heart-rate-variability', 'daily_heart_rate_variability.date >= "' + startDate + '"', 100),
  list('sleep', 'sleep', 'sleep.interval.end_time >= "' + startUtc + '"', 25),
  list('exercise', 'exercise', 'exercise.interval.civil_start_time >= "' + startDate + '"', 25),
];
return requests.map(r => ({ json: { ...r, window_start: start.toUTC().toISO(), window_end: now.toUTC().toISO() } }));

const tz = 'Europe/Rome';
const reqs = $('Build sync window').all().map(i => i.json);
const rollReqs = reqs.filter(r => r.kind === 'rollup');
const listReqs = reqs.filter(r => r.kind === 'list');
const pairs = [];
$('Fetch daily roll-ups').all().forEach((r, i) => pairs.push([rollReqs[i], r.json]));
$('Fetch health records').all().forEach((r, i) => pairs.push([listReqs[i], r.json]));
const nowMs = Date.now();
const out = [];
const round = v => Math.round(Number(v) * 100) / 100;
const add = (metric, value, unit, startIso, endIso, details) => {
  if (value === null || value === undefined || value === '' || Number.isNaN(Number(value))) return;
  const endMs = Math.min(new Date(endIso).getTime(), nowMs);
  out.push({
    athlete_id: 'athlete',
    source: 'google_health',
    metric,
    value: round(value),
    unit,
    details: details || null,
    period_start: new Date(startIso).toISOString(),
    recorded_at: new Date(endMs).toISOString(),
  });
};
const dayStart = d => DateTime.fromObject({ year: d.year, month: d.month, day: d.day }, { zone: tz });
const secs = s => Number(String(s || '0').replace('s', ''));

pairs.forEach(([req, json]) => {
  const body = json || {};
  if (!req || body.error) return;
  const metric = req.metric;
  if (req.kind === 'rollup') {
    for (const p of body.rollupDataPoints || []) {
      const d = p.civilStartTime && p.civilStartTime.date;
      if (!d) continue;
      const s = dayStart(d);
      const S = s.toISO();
      const E = s.plus({ days: 1 }).toISO();
      if (metric === 'steps' && p.steps) add('steps', p.steps.countSum, 'count', S, E);
      if (metric === 'distance' && p.distance) add('distance', Number(p.distance.millimetersSum) / 1e6, 'km', S, E);
      if (metric === 'calories' && p.totalCalories) add('calories_expended', p.totalCalories.kcalSum, 'kcal', S, E);
      if (metric === 'active_minutes' && p.activeMinutes) {
        const lv = p.activeMinutes.activeMinutesRollupByActivityLevel || [];
        const total = lv.reduce((a, x) => a + Number(x.activeMinutesSum || 0), 0);
        add('active_minutes', total, 'min', S, E, lv.map(x => x.activityLevel + ': ' + x.activeMinutesSum).join(', '));
      }
      if (metric === 'active_zone_minutes' && p.activeZoneMinutes) {
        const z = p.activeZoneMinutes;
        const fb = Number(z.sumInFatBurnHeartZone || 0);
        const c = Number(z.sumInCardioHeartZone || 0);
        const pk = Number(z.sumInPeakHeartZone || 0);
        add('active_zone_minutes', fb + c + pk, 'min', S, E, 'fat_burn ' + fb + ', cardio ' + c + ', peak ' + pk);
      }
      if (metric === 'heart_rate' && p.heartRate) {
        add('heart_rate_avg', p.heartRate.beatsPerMinuteAvg, 'bpm', S, E);
        add('heart_rate_max', p.heartRate.beatsPerMinuteMax, 'bpm', S, E);
        add('heart_rate_min', p.heartRate.beatsPerMinuteMin, 'bpm', S, E);
      }
      if (metric === 'weight' && p.weight) add('weight', Number(p.weight.weightGramsAvg) / 1000, 'kg', S, E);
    }
    return;
  }
  for (const dp of body.dataPoints || []) {
    if (metric === 'resting_heart_rate' && dp.dailyRestingHeartRate && dp.dailyRestingHeartRate.date) {
      const s = dayStart(dp.dailyRestingHeartRate.date);
      add('resting_heart_rate', dp.dailyRestingHeartRate.beatsPerMinute, 'bpm', s.toISO(), s.plus({ days: 1 }).toISO());
    }
    if (metric === 'hrv' && dp.dailyHeartRateVariability && dp.dailyHeartRateVariability.date) {
      const v = dp.dailyHeartRateVariability;
      const s = dayStart(v.date);
      add('hrv_avg', v.averageHeartRateVariabilityMilliseconds, 'ms', s.toISO(), s.plus({ days: 1 }).toISO());
      add('hrv_deep_sleep_rmssd', v.deepSleepRootMeanSquareOfSuccessiveDifferencesMilliseconds, 'ms', s.toISO(), s.plus({ days: 1 }).toISO());
    }
    if (metric === 'sleep' && dp.sleep && dp.sleep.interval) {
      const sl = dp.sleep;
      const S = sl.interval.startTime;
      const E = sl.interval.endTime;
      const sm = sl.summary || {};
      const asleepMin = sm.minutesAsleep !== undefined ? Number(sm.minutesAsleep) : (new Date(E) - new Date(S)) / 60000;
      add('sleep_hours', asleepMin / 60, 'h', S, E, sl.type || null);
      add('sleep_awake_minutes', sm.minutesAwake, 'min', S, E);
      add('sleep_minutes_to_fall_asleep', sm.minutesToFallAsleep, 'min', S, E);
      for (const st of sm.stagesSummary || []) {
        const t = String(st.type || '').toLowerCase();
        if (['deep', 'rem', 'light'].includes(t)) add('sleep_' + t + '_minutes', st.minutes, 'min', S, E);
        if (t === 'awake') add('sleep_awakenings', st.count, 'count', S, E);
      }
    }
    if (metric === 'exercise' && dp.exercise && dp.exercise.interval) {
      const ex = dp.exercise;
      const S = ex.interval.startTime;
      const E = ex.interval.endTime;
      const ms = ex.metricsSummary || {};
      const minutes = ex.activeDuration ? secs(ex.activeDuration) / 60 : (new Date(E) - new Date(S)) / 60000;
      const parts = [ex.displayName || ex.exerciseType || 'workout'];
      if (ex.exerciseType) parts.push('type ' + ex.exerciseType);
      if (ms.distanceMillimeters) parts.push(round(ms.distanceMillimeters / 1e6) + ' km');
      if (ms.caloriesKcal) parts.push(round(ms.caloriesKcal) + ' kcal');
      if (ms.averageHeartRateBeatsPerMinute) parts.push('avg HR ' + ms.averageHeartRateBeatsPerMinute + ' bpm');
      if (ms.activeZoneMinutes) parts.push(ms.activeZoneMinutes + ' AZM');
      if (ms.steps) parts.push(ms.steps + ' steps');
      add('workout_minutes', minutes, 'min', S, E, parts.join(' | '));
    }
  }
});
return out.map(json => ({ json }));

const w = $('Build sync window').first().json;
const rows = $('Normalize samples').all().map(i => i.json);
const reqs = $('Build sync window').all().map(i => i.json);
const errOf = (items, list) => items.map((r, i) => (r.json && r.json.error ? (list[i] ? list[i].metric : 'request ' + i) + ': ' + String(r.json.error.message || JSON.stringify(r.json.error)).slice(0, 200) : null));
const errors = errOf($('Fetch daily roll-ups').all(), reqs.filter(r => r.kind === 'rollup'))
  .concat(errOf($('Fetch health records').all(), reqs.filter(r => r.kind === 'list')))
  .filter(Boolean);
return [{ json: {
  synced_rows: rows.length,
  errors,
  window_start: w.window_start,
  window_end: w.window_end,
  metrics: [...new Set(rows.map(r => r.metric))],
} }];
